const getGoodsList = `-- name: GetGoodsList :many
WITH goods_list AS (
    SELECT
        g.id,
        COALESCE(
            CASE
                WHEN $6::text = 'uz' THEN tn.uz
                WHEN $6::text = 'ru' THEN tn.ru
                WHEN $6::text = 'en' THEN tn.en
                ELSE g.name
            END,
            g.name
        ) AS name,
        COALESCE(
            CASE
                WHEN $6::text = 'uz' THEN td.uz
                WHEN $6::text = 'ru' THEN td.ru
                WHEN $6::text = 'en' THEN td.en
                ELSE g.description
            END,
            g.description
        ) AS description,
        g.name_i18n,
        g.description_i18n,
        g.category_id,
        g.branch_id,
        g.picture_url,
        g.color_code,
        g.price,
        g.cook_time,
        g.cost_price,
        g.profit,
        g.profit_margin,
        g.created_at,
        g.updated_at,
        g.deleted_at
    FROM goods g
    LEFT JOIN categories c
        ON g.category_id = c.id
       AND c.deleted_at = 0
    LEFT JOIN departments d
        ON c.department_id = d.id
       AND d.deleted_at = 0
    LEFT JOIN translations tn
        ON g.name_i18n = tn.id
       AND tn.deleted_at = 0
    LEFT JOIN translations td
        ON g.description_i18n = td.id
       AND td.deleted_at = 0
    WHERE g.deleted_at = 0
      AND g.branch_id = NULLIF(current_setting('app.branch_id', true), '')::uuid
      AND (
            $7::uuid IS NULL
            OR g.category_id = $7::uuid
          )
      AND (
            $8::uuid IS NULL
            OR c.department_id = $8::uuid
          )
      AND (
            $9::uuid IS NULL
            OR d.storage_id = $9::uuid
          )
      AND (
            $10::numeric IS NULL
            OR g.price >= $10::numeric
          )
      AND (
            $11::numeric IS NULL
            OR g.price <= $11::numeric
          )
)
SELECT
    id,
    name,
    description,
    name_i18n,
    description_i18n,
    category_id,
    branch_id,
    picture_url,
    color_code,
    price,
    cook_time,
    cost_price,
    profit,
    profit_margin,
    created_at,
    updated_at,
    deleted_at
FROM goods_list
WHERE (
        $1::text = ''
        OR name ILIKE '%' || $1::text || '%'
        OR COALESCE(description, '') ILIKE '%' || $1::text || '%'
      )
ORDER BY
    CASE
        WHEN $2::text = 'name' AND $3::text = 'asc'
        THEN name
    END ASC,
    CASE
        WHEN $2::text = 'name' AND $3::text = 'desc'
        THEN name
    END DESC,
    CASE
        WHEN $2::text = 'price' AND $3::text = 'asc'
        THEN price
    END ASC,
    CASE
        WHEN $2::text = 'price' AND $3::text = 'desc'
        THEN price
    END DESC,
    CASE
        WHEN $2::text = 'created_at' AND $3::text = 'asc'
        THEN created_at
    END ASC,
    CASE
        WHEN $2::text = 'created_at' AND $3::text = 'desc'
        THEN created_at
    END DESC,
    created_at DESC
LIMIT $5::int
OFFSET $4::int
`

